import React from 'react';
import { ExternalLink, Clock, Target } from 'lucide-react';

const RoadmapItem = ({ gap }) => {
  const priorityStyles = {
    High: 'bg-gold-300/20 text-gold-300 border-gold-300/40 shadow-gold-glow',
    Medium: 'bg-bronze-600/30 text-bronze-100 border-bronze-100/30',
    Low: 'bg-bronze-800/40 text-bronze-200 border-bronze-400/30',
  };

  return (
    <div className="glass-card p-5 rounded-2xl border border-bronze-100/15 mb-4 transition-all duration-300 hover:border-gold-300/40">
      <div className="flex items-center justify-between mb-2">
        <div className="flex items-center space-x-2">
          <Target className="w-5 h-5 text-gold-300" />
          <h4 className="font-heading font-bold text-lg text-bronze-100">{gap.skill}</h4>
        </div>
        <span className={`px-3 py-1 rounded-full text-xs font-mono font-semibold border ${
          priorityStyles[gap.priority] || priorityStyles.Medium
        }`}>
          {gap.priority} Priority
        </span>
      </div>

      <div className="flex items-center space-x-2 text-xs font-mono text-bronze-200 mb-4">
        <Clock className="w-3.5 h-3.5 text-gold-300" />
        <span>Estimated Mastery Time: {gap.estimated_time || '1-2 weeks'}</span>
      </div>

      {gap.resources && gap.resources.length > 0 && (
        <div className="pt-3 border-t border-bronze-100/15 space-y-2">
          <p className="text-[11px] font-mono uppercase tracking-wider text-bronze-200 font-semibold">
            Curated Learning Resources:
          </p>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
            {gap.resources.map((resource, index) => (
              <a
                key={index}
                href={resource.url}
                target="_blank"
                rel="noopener noreferrer"
                className="p-2.5 rounded-xl bg-bronze-950/80 border border-bronze-100/15 flex items-center justify-between text-xs text-gold-300 hover:text-bronze-100 hover:border-gold-300/50 hover:bg-bronze-800/50 transition-all group"
              >
                <span className="truncate">{resource.name}</span>
                <ExternalLink className="w-3.5 h-3.5 text-gold-300 group-hover:scale-110 transition-transform shrink-0 ml-2" />
              </a>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export default RoadmapItem;
